files.hooks/register.ts:
// handoff-guard: never lose a session to the context limit.
//
// session.start        loads config, reads context fill, registers /handoff; seeds a session
//                      that missed the clear signal (resume-before-load race, from session-saver)
// classic.SessionStart after /clear: reloads config ($.state was reset) and submits the one-line
//                      resume prompt queued in $.store by the handoff that cleared
// turn.step            before each main-loop request: measures fill (plus tool output not yet
//                      measured) so a long tool-heavy turn is caught mid-turn; past handoffAt it
//                      asks (ask) or hands off (auto) and ends the turn
// turn.complete        after each main-loop turn: measures, warns once at warnAt, asks or hands off
// tool.call            records edited files; in auto mode past denyAt refuses new calls
// session.compact      writes the handoff first when none was written since the last clear, then
//                      lets compaction proceed (never blocks it)
// command.run          /handoff and its subcommands
// ui.render            the one-line band (stacks other mods' band under it) and the pane
//
// State that must survive /clear (the queued resume prompt, the last brief, settings) lives in
// $.store; $.state is reset by /clear, which is exactly the per-session state we want reset.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { BriefInfo, Config, Reading } from '../types'
import {
  DEFAULTS,
  EDIT_TOOLS,
  FILE_HEADERS,
  HELP,
  MODES,
  appendLine,
  bandParts,
  briefMarkdown,
  buildSections,
  clip,
  completePrompt,
  datedLine,
  dateOf,
  extractFromMessages,
  factsBlock,
  forkPrompt,
  isMeta,
  levelOf,
  markUnverifiedFigures,
  mergeConfig,
  parseBrief,
  parseFraction,
  pct,
  projectTemplate,
  readingOf,
  renderTranscript,
  replaceSection,
  sanitize,
  setFrontmatter,
  slugOf,
  upsertLogLine,
  whenOf,
  wordsFor,
} from './logic'
import { LEVEL_TONE } from './logic'
import type { Facts, Msg, Parsed, Sections } from './logic'
import { TONES, makeKit, tokensShort } from './kit'
import type { Elements, Tone } from './kit'

type Api = EngineInterface

const PANE = 'handoff-guard'
const SETTINGS_KEY = 'settings'
const CONFIG_FILE = '.claude/handoff-guard.json'
const BRAIN_DIR = '.claude/brain'
const PENDING_TTL_MS = 15 * 60_000
const RACE_TTL_MS = 2 * 60_000
const CHARS_PER_TOKEN = 4
const CLEAR_DELAY_MS = 250
const ASK_NOW = 'Handoff now'
const ASK_OFF = 'Off this session'

const configAtom = atom({ plugin: 'lk-handoff-guard', key: 'config' } as const, DEFAULTS)
const readingAtom = atom({ plugin: 'lk-handoff-guard', key: 'reading' } as const, null as Reading | null)
const historyAtom = atom({ plugin: 'lk-handoff-guard', key: 'history' } as const, [] as Reading[])
const warnedAtom = atom({ plugin: 'lk-handoff-guard', key: 'warned' } as const, false)
const nextAskAtom = atom({ plugin: 'lk-handoff-guard', key: 'nextAskAt' } as const, 0)
const askedOutAtom = atom({ plugin: 'lk-handoff-guard', key: 'askedOut' } as const, false)
const sessionOffAtom = atom({ plugin: 'lk-handoff-guard', key: 'sessionOff' } as const, false)
const autoTriedAtom = atom({ plugin: 'lk-handoff-guard', key: 'autoTried' } as const, false)
const writtenAtom = atom({ plugin: 'lk-handoff-guard', key: 'written' } as const, false)
const clearingAtom = atom({ plugin: 'lk-handoff-guard', key: 'clearing' } as const, false)
const busyAtom = atom({ plugin: 'lk-handoff-guard', key: 'busy' } as const, false)
const editedSessionAtom = atom({ plugin: 'lk-handoff-guard', key: 'editedSession' } as const, [] as string[])
const editedTurnAtom = atom({ plugin: 'lk-handoff-guard', key: 'editedTurn' } as const, [] as string[])
const lastBriefAtom = atom({ plugin: 'lk-handoff-guard', key: 'lastBrief' } as const, null as BriefInfo | null)
const resumedAtom = atom({ plugin: 'lk-handoff-guard', key: 'resumed' } as const, '')
const cwdAtom = atom({ plugin: 'lk-handoff-guard', key: 'cwd' } as const, '')

// Module variables: a guard against two handoffs at once, and tool output that has landed
// since the last measured response (borrowed from auto-handoff's "unmeasured").
let inFlight = false
let unmeasured = 0

type Pending = { at: number; when: string; path: string; from: string }

// ---------------------------------------------------------------- small helpers

const capPreview = (text: string) => (text.length > 6000 ? text.slice(0, 6000) + '\n…' : text)

const errText = (err: unknown) => (err instanceof Error ? err.message : String(err))

function toast($: Api, text: string): void {
  try {
    $.ui.toast(text)
  } catch {
    // Display only.
  }
}

async function now($: Api): Promise<number> {
  try {
    const t = await $.clock.now()
    return typeof t === 'number' && Number.isFinite(t) ? t : Date.now()
  } catch {
    return Date.now()
  }
}

async function cwdOf($: Api): Promise<string> {
  const held = await read($, cwdAtom)
  if (held) return held
  try {
    const c = await $.session.cwd()
    if (typeof c === 'string' && c) {
      await update($, cwdAtom, () => c)
      return c
    }
  } catch {
    // Fall through.
  }
  return ''
}

async function sessionId($: Api): Promise<string> {
  try {
    return String((await $.session.id()) ?? '')
  } catch {
    return ''
  }
}

const join = (dir: string, rel: string) => (dir ? dir.replace(/\/+$/, '') + '/' + rel : rel)

async function readText($: Api, path: string): Promise<string | null> {
  try {
    if (!(await $.fs.exists(path))) return null
    const t = await $.fs.read(path)
    return typeof t === 'string' ? t : null
  } catch {
    return null
  }
}

async function readJson($: Api, path: string): Promise<unknown> {
  const t = await readText($, path)
  if (t === null) return null
  try {
    return JSON.parse(t)
  } catch {
    return null
  }
}

async function storeGet($: Api, key: string): Promise<unknown> {
  try {
    return await $.store.get(key)
  } catch {
    return undefined
  }
}

// ---------------------------------------------------------------- config

async function loadConfig($: Api): Promise<Config> {
  let home = ''
  try {
    home = (await $.env.get('HOME')) ?? ''
  } catch {
    home = ''
  }
  const cwd = await cwdOf($)
  const user = home ? await readJson($, join(home, CONFIG_FILE)) : null
  const project = cwd ? await readJson($, join(cwd, CONFIG_FILE)) : null
  const saved = await storeGet($, SETTINGS_KEY)
  const cfg = mergeConfig(user, project, saved)
  await update($, configAtom, () => cfg)
  return cfg
}

async function saveSetting($: Api, patch: Partial<Config>): Promise<Config> {
  const saved = sanitize(await storeGet($, SETTINGS_KEY))
  await $.store.set(SETTINGS_KEY, { ...saved, ...patch })
  return loadConfig($)
}

/** The last brief for this project, from $.store, so /handoff status and the pane survive /clear. */
async function loadLast($: Api): Promise<void> {
  const cwd = await cwdOf($)
  const v = (await storeGet($, 'last:' + cwd)) as BriefInfo | undefined
  if (v && typeof v === 'object' && typeof v.path === 'string' && typeof v.when === 'string') {
    await update($, lastBriefAtom, () => v)
  }
}

// ---------------------------------------------------------------- measurement

async function measure($: Api, where: string, extraTokens = 0): Promise<Reading | null> {
  try {
    const u = await $.session.usage()
    const r = readingOf(u && (u as { context?: unknown }).context, await now($), where, extraTokens)
    if (!r) return null
    await update($, readingAtom, () => r)
    await update($, historyAtom, (h: Reading[]) => [...h, r].slice(-30))
    return r
  } catch {
    return null
  }
}

/** Warns once at warnAt; past handoffAt asks, hands off or does nothing by mode. 'stop' ends the turn. */
async function evaluate($: Api, r: Reading, where: 'start' | 'step' | 'complete'): Promise<'stop' | 'none'> {
  const cfg = await read($, configAtom)
  const level = levelOf(r.frac, cfg)
  if (level !== 'ok' && !(await read($, warnedAtom))) {
    await update($, warnedAtom, () => true)
    toast($, `context ${pct(r.frac)}%: run /handoff when you reach a stopping point`)
  }
  if (where === 'start' || level !== 'due') return 'none'
  if (cfg.mode === 'off' || (await read($, sessionOffAtom))) return 'none'
  if (inFlight || (await read($, clearingAtom))) return 'none'

  if (cfg.mode === 'auto') {
    if (await read($, autoTriedAtom)) return 'none'
    await update($, autoTriedAtom, () => true)
    const info = await doHandoff($, true)
    return info ? 'stop' : 'none'
  }

  // ask
  if (await read($, askedOutAtom)) return 'none'
  const nextAsk = await read($, nextAskAtom)
  const threshold = nextAsk > 0 ? nextAsk : cfg.handoffAt
  if (r.frac < threshold) return 'none'
  const first = threshold < cfg.reaskAt
  const later = first ? `Later (ask at ${pct(cfg.reaskAt)}%)` : 'Later'
  let answer = later
  try {
    answer = await $.ui.ask(`Context at ${pct(r.frac)}%. Write the handoff and clear now?`, {
      options: [ASK_NOW, later, ASK_OFF],
      header: 'Handoff',
    })
  } catch {
    // Dismissed, or nobody to ask (-p): treat as Later.
    answer = later
  }
  if (answer === ASK_NOW) {
    const info = await doHandoff($, true)
    return info ? 'stop' : 'none'
  }
  if (answer === ASK_OFF) {
    await update($, sessionOffAtom, () => true)
    toast($, 'handoff-guard: off for this session. /handoff still writes one.')
    return 'none'
  }
  if (first) await update($, nextAskAtom, () => cfg.reaskAt)
  else await update($, askedOutAtom, () => true)
  return 'none'
}

// ---------------------------------------------------------------- the handoff

async function git($: Api, cwd: string, argv: string[]): Promise<string> {
  try {
    const r = await $.process.run(['git', ...argv], { cwd: cwd || undefined, timeoutMs: 5000 })
    return r && r.exitCode === 0 && typeof r.stdout === 'string' ? r.stdout.trim() : ''
  } catch {
    return ''
  }
}

async function loopkeeperStage($: Api): Promise<string> {
  try {
    // The loopkeeper core's stage, not in this contract: typed loosely and read only when present.
    const got = (await $.state.get({ plugin: 'loopkeeper', key: 'stageCurrent' } as never)) as { value?: unknown } | undefined
    return got && typeof got.value === 'string' ? got.value : ''
  } catch {
    return ''
  }
}

async function messagesOf($: Api): Promise<Msg[]> {
  try {
    const m = await $.session.messages()
    return Array.isArray(m) ? (m as unknown as Msg[]) : []
  } catch {
    return []
  }
}

async function collectFacts($: Api, messages: Msg[]): Promise<Facts> {
  const cwd = await cwdOf($)
  const branch = await git($, cwd, ['rev-parse', '--abbrev-ref', 'HEAD'])
  const log = await git($, cwd, ['log', '-5', '--pretty=format:%h %s'])
  const x = extractFromMessages(messages)
  const seen = await read($, editedSessionAtom)
  const editedSession = [...new Set([...x.edited, ...seen])]
  const r = await read($, readingAtom)
  return {
    cwd,
    when: whenOf(await now($)),
    branch,
    commits: log ? log.split('\n').map(l => clip(l, 120)).filter(Boolean).slice(0, 5) : [],
    editedTurn: await read($, editedTurnAtom),
    editedSession,
    lastPrompt: x.lastPrompt,
    lastAnswer: x.lastAnswer,
    openQuestions: x.openQuestions,
    stage: await loopkeeperStage($),
    ctxPercent: r ? pct(r.frac) : null,
    ctxTokens: r ? r.tokens : null,
    ctxWindow: r ? r.window : null,
  }
}

/** Fork first (shares the session's prompt cache), then complete; null when neither gives all headings. */
async function draft($: Api, cfg: Config, facts: string, messages: Msg[]): Promise<{ parsed: Parsed | null; source: string; flagged: string[] }> {
  const words = wordsFor(cfg.maxBriefTokens)
  const tryText = (text: unknown, source: string) => {
    if (typeof text !== 'string' || !parseBrief(text)) return null
    const checked = markUnverifiedFigures(text, facts)
    const parsed = parseBrief(checked.text)
    return parsed ? { parsed, source, flagged: checked.flagged } : null
  }
  try {
    const r = await $.model.fork({ prompt: forkPrompt(facts, words) })
    const got = r && r.isAnswered ? tryText(r.text, 'fork') : null
    if (got) return got
  } catch {
    // Fall back to complete.
  }
  try {
    const r = await $.model.complete({
      model: cfg.model,
      system: 'You write short, precise handoff notes for coding sessions.',
      prompt: completePrompt(facts, renderTranscript(messages), words),
      maxTokens: cfg.maxBriefTokens,
      timeoutMs: 60_000,
    })
    const got = r && r.isAnswered ? tryText(r.text, 'complete') : null
    if (got) return got
  } catch {
    // Facts only.
  }
  return { parsed: null, source: 'facts', flagged: [] }
}

/** Writes project.md sections, a log line, decisions and questions in the handoff folder's shapes. */
async function writeBrain($: Api, cwd: string, s: Sections, at: number, sid: string): Promise<string> {
  const dir = join(cwd, BRAIN_DIR)
  const date = dateOf(at)
  const projectPath = join(dir, 'project.md')
  let project = (await readText($, projectPath)) ?? projectTemplate(slugOf(cwd), date)
  project = replaceSection(project, 'Status today', s.status)
  project = replaceSection(project, 'Next', s.next)
  if (s.deadEnds) project = replaceSection(project, 'Dead ends', s.deadEnds)
  project = setFrontmatter(project, 'updated', date)
  await $.fs.write(projectPath, project)

  const logPath = join(dir, 'log.md')
  const logLine = datedLine(date, s.log)
  const prevKey = 'logline:' + cwd
  const prev = (await storeGet($, prevKey)) as { sid?: string; line?: string } | undefined
  const previous = prev && prev.sid === sid && typeof prev.line === 'string' ? prev.line : undefined
  const logDoc = (await readText($, logPath)) ?? FILE_HEADERS['log.md']
  await $.fs.write(logPath, upsertLogLine(logDoc, logLine, previous))
  try {
    await $.store.set(prevKey, { sid, line: logLine })
  } catch {
    // The next handoff appends instead of replacing.
  }

  for (const [file, items] of [
    ['decisions.md', s.decisions],
    ['questions.md', s.questions],
  ] as const) {
    if (!items.length) continue
    const path = join(dir, file)
    let doc = (await readText($, path)) ?? FILE_HEADERS[file]
    for (const item of items) doc = appendLine(doc, datedLine(date, item)).doc
    await $.fs.write(path, doc)
  }
  return projectPath
}

/** The whole handoff. With clear, queues the resume prompt in $.store and then /clear. */
async function doHandoff($: Api, clear: boolean): Promise<BriefInfo | null> {
  if (inFlight) return null
  inFlight = true
  await update($, busyAtom, () => true)
  try {
    const cfg = await read($, configAtom)
    const cwd = await cwdOf($)
    const sid = await sessionId($)
    const messages = await messagesOf($)
    const facts = await collectFacts($, messages)
    const factsText = factsBlock(facts)
    const { parsed, source, flagged } = await draft($, cfg, factsText, messages)
    const sections = buildSections(parsed, facts)
    const at = await now($)
    const path = await writeBrain($, cwd, sections, at, sid)
    const info: BriefInfo = {
      at,
      when: whenOf(at),
      path,
      sessionId: sid,
      source,
      flagged,
      preview: capPreview(briefMarkdown(sections, factsText)),
    }
    await update($, lastBriefAtom, () => info)
    await update($, writtenAtom, () => true)
    try {
      await $.store.set('last:' + cwd, info)
    } catch {
      // Status after /clear falls back to nothing.
    }
    const shown = path.startsWith(cwd + '/') ? path.slice(cwd.length + 1) : path
    toast($, `Handoff written: ${shown}${source === 'facts' ? ' (facts only)' : ''}${flagged.length ? ` · ${flagged.length} unverified figure(s)` : ''}`)
    if (clear) {
      const pending: Pending = { at, when: info.when, path, from: sid }
      await $.store.set('pending:' + cwd, pending)
      await update($, clearingAtom, () => true)
      // From a timer, outside any event: a command.run hook may not run a command, and a
      // turn.step hook holds the turn. Not awaited: /clear runs once the session is idle.
      $.clock.after(CLEAR_DELAY_MS, () => runClear($, cwd, shown))
    }
    return info
  } catch (err) {
    toast($, 'handoff-guard: the handoff failed: ' + errText(err))
    return null
  } finally {
    inFlight = false
    try {
      await update($, busyAtom, () => false)
    } catch {
      // Display only.
    }
  }
}

function runClear($: Api, cwd: string, shown: string): void {
  $.command.run({ command: 'clear' }).catch(async (err: unknown) => {
    toast($, `handoff-guard: /clear was refused (${errText(err)}); the handoff is at ${shown}`)
    try {
      await $.store.delete('pending:' + cwd)
      await update($, clearingAtom, () => false)
    } catch {
      // Nothing else to undo.
    }
  })
}

/** After /clear: submit the one-line resume prompt the handoff queued, once. */
async function consumePending($: Api, maxAgeMs: number): Promise<boolean> {
  const cwd = await cwdOf($)
  const key = 'pending:' + cwd
  const p = (await storeGet($, key)) as Pending | undefined
  if (!p || typeof p !== 'object' || typeof p.when !== 'string' || typeof p.at !== 'number') return false
  try {
    await $.store.delete(key)
  } catch {
    return false // Never risk submitting twice.
  }
  if ((await now($)) - p.at > maxAgeMs) return false
  await update($, resumedAtom, () => p.when)
  const text = `Resume from the handoff in .claude/brain/project.md (written ${p.when}); read it first.`
  // Not awaited: it resolves when the new turn starts.
  $.prompt.submit({ text }).catch(() => {
    toast($, `handoff-guard: could not start the resume turn; read .claude/brain/project.md (written ${p.when})`)
  })
  return true
}

/** Resets per-session state and reloads what a fresh session needs (after start or /clear). */
async function onStart($: Api, cwd: string): Promise<void> {
  if (cwd) await update($, cwdAtom, () => cwd)
  unmeasured = 0
  await loadConfig($)
  await loadLast($)
  const r = await measure($, 'start')
  if (r) await evaluate($, r, 'start')
}

// ---------------------------------------------------------------- pane helpers (pure)

/** The quiet color of the kit (secondary text), a theme key. */
const QUIET = TONES.muted.fg

/** The pane's hero line: the handoff state, in the words the band uses. */
function heroTitle(r: Reading | null, cfg: Config, o: { busy: boolean; sessionOff: boolean }): string {
  if (o.busy) return 'Writing the handoff…'
  if (!r) return 'Context: no reading yet'
  const ctx = `Context ${pct(r.frac)}%`
  const level = levelOf(r.frac, cfg)
  if (level === 'due') {
    if (cfg.mode === 'off' || o.sessionOff) return `${ctx} · handoff due · guard off`
    return cfg.mode === 'auto' ? `${ctx} · handoff due · auto handoff` : `${ctx} · handoff due: /handoff clear`
  }
  if (level === 'warn') return `${ctx} · /handoff at a stopping point`
  return `${ctx} · next handoff at ${pct(cfg.handoffAt)}%`
}

// ---------------------------------------------------------------- /handoff

async function statusText($: Api): Promise<string> {
  const cfg = await read($, configAtom)
  const r = await read($, readingAtom)
  const last = await read($, lastBriefAtom)
  const off = await read($, sessionOffAtom)
  const ctx = r
    ? `Context ${pct(r.frac)}%` + (r.tokens !== null && r.window !== null ? ` (${r.tokens} of ${r.window} tokens)` : '')
    : 'Context: no reading yet'
  const lines = [
    `${ctx} · warn ${pct(cfg.warnAt)}% · handoff ${pct(cfg.handoffAt)}% · mode ${cfg.mode}${off ? ' (off this session)' : ''}`,
    last ? `Last handoff: ${last.when} (${last.source}) at ${last.path}` : 'Last handoff: none for this project yet',
  ]
  return lines.join('\n')
}

async function runCommand($: Api, args: string): Promise<{ text?: string }> {
  const words = args.trim().split(/\s+/).filter(Boolean)
  const sub = (words[0] ?? '').toLowerCase()
  const arg = words.slice(1).join(' ').toLowerCase()
  if (sub === '' || sub === 'now' || sub === 'write') {
    const info = await doHandoff($, false)
    return { text: info ? `Handoff written to ${info.path} (${info.source}).` : 'handoff-guard: no handoff written (one is already running, or it failed).' }
  }
  if (sub === 'clear') {
    const info = await doHandoff($, true)
    return {
      text: info
        ? `Handoff written to ${info.path} (${info.source}). Clearing; the next session resumes from it.`
        : 'handoff-guard: no handoff written, so nothing was cleared.',
    }
  }
  if (sub === 'status') return { text: await statusText($) }
  if (sub === 'show' || sub === 'pane') {
    await $.ui.open({ id: PANE, title: 'Handoff guard', focus: true, closeOnEscape: true })
    return {}
  }
  if (sub === 'mode') {
    if (!(MODES as readonly string[]).includes(arg)) return { text: 'Mode must be ask, auto or off.' }
    const cfg = await saveSetting($, { mode: arg as Config['mode'] })
    if (arg !== 'off') await update($, sessionOffAtom, () => false)
    return { text: cfg.mode === arg ? `Mode set to ${arg}.` : `Mode saved as ${arg}, but a config file overrides it: ${cfg.mode}.` }
  }
  if (sub === 'at' || sub === 'warn') {
    const f = parseFraction(arg)
    if (f === null) return { text: 'Give a fraction between 0 and 1, such as 0.85.' }
    const cfg = await saveSetting($, sub === 'at' ? { handoffAt: f } : { warnAt: f })
    if (sub === 'at') {
      await update($, nextAskAtom, () => 0)
      await update($, askedOutAtom, () => false)
      await update($, autoTriedAtom, () => false)
    } else {
      await update($, warnedAtom, () => false)
    }
    return { text: `Warning at ${pct(cfg.warnAt)}%, handoff at ${pct(cfg.handoffAt)}%.` }
  }
  if (sub === 'band') {
    if (arg !== 'on' && arg !== 'off') return { text: 'Use /handoff band on or /handoff band off.' }
    const cfg = await saveSetting($, { band: arg === 'on' })
    return { text: cfg.band ? 'Band shown above the prompt.' : 'Band hidden.' }
  }
  return { text: HELP }
}

// ---------------------------------------------------------------- hooks

export function register(on: On) {
  on('session.start', async ($, e, next) => {
    try {
      await onStart($, typeof e.cwd === 'string' ? e.cwd : '')
    } catch {
      // Defaults stay in place.
    }
    // The clear signal can fire before this module loads (a reload at the wrong moment): a
    // fresh queued resume and an empty transcript count too (session-saver's race guard).
    try {
      if ((await messagesOf($)).length === 0) await consumePending($, RACE_TTL_MS)
    } catch {
      // The pending entry stays for classic.SessionStart.
    }
    try {
      await $.command.register({
        name: 'handoff',
        description: 'Write the brain handoff now; or clear, status, show, mode, at, warn, band',
        argumentHint: '[clear | status | show | mode ask|auto|off | at <0-1> | warn <0-1> | band on|off]',
        immediate: true,
      })
    } catch {
      // The name is taken: measuring and the band still work.
    }
    return next(e)
  })

  // /clear (and /resume, /branch) reset $.state without a session.start.
  on('classic.SessionStart', async ($, e, next) => {
    const result = await next(e)
    const source = typeof e.source === 'string' ? e.source : ''
    if (source === 'clear' || source === 'resume' || source === 'compact') {
      try {
        await onStart($, typeof e.cwd === 'string' ? e.cwd : '')
      } catch {
        // Defaults stay in place.
      }
    }
    if (source === 'clear') {
      try {
        await consumePending($, PENDING_TTL_MS)
      } catch {
        // Nothing queued.
      }
    }
    return result
  })

  on('prompt.submit', async ($, e, next) => {
    try {
      const kind = e.origin && typeof e.origin === 'object' ? (e.origin as { kind?: string; asUser?: boolean }) : undefined
      const typed = !kind || ['composer', 'bridge', 'sdk'].includes(String(kind.kind)) || kind.asUser === true
      if (typed && typeof e.text === 'string' && !isMeta(e.text) && (await read($, resumedAtom))) {
        await update($, resumedAtom, () => '')
      }
    } catch {
      // Display only.
    }
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    try {
      if (!e.agentId) await update($, editedTurnAtom, () => [])
    } catch {
      // Observing only.
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (!e.agentId) {
      let stop = false
      try {
        const r = await measure($, 'step', Math.ceil(unmeasured))
        // Index 0 follows a turn.complete reading; act on the requests after tool calls.
        if (r && typeof e.index === 'number' && e.index > 0) stop = (await evaluate($, r, 'step')) === 'stop'
      } catch {
        stop = false
      }
      if (stop) {
        unmeasured = 0
        yield { kind: 'text', index: 0, text: '[handoff-guard] Context is nearly full: the handoff is written to .claude/brain/ and this session is clearing.' } as never
        yield { kind: 'stop', stopReason: 'end_turn', usage: null } as never
        return { turnId: e.turnId, index: e.index, answer: '', toolUses: [], stopReason: 'end_turn', usage: null } as never
      }
    }
    const result = yield* next(e)
    if (!e.agentId) unmeasured = 0
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (!e.agentId) {
      try {
        unmeasured = 0
        const r = await measure($, 'complete')
        if (r) await evaluate($, r, 'complete')
      } catch {
        // Observing only.
      }
    }
    return result
  })

  on('tool.call', async ($, e, next) => {
    let deny: string | null = null
    try {
      const tool = typeof e.tool === 'string' ? e.tool : ''
      const exempt = tool === 'AskUserQuestion' || tool.startsWith('mcp__handoff-guard__') || (typeof e.consent === 'string' && e.consent !== '')
      if (!exempt) {
        const cfg = await read($, configAtom)
        // Only auto mode refuses, so only auto mode pays for a fresh reading here.
        const r = cfg.mode === 'auto' && !e.agentId ? ((await measure($, 'tool', Math.ceil(unmeasured))) ?? (await read($, readingAtom))) : null
        if (r && !(await read($, sessionOffAtom)) && r.frac >= cfg.denyAt) {
          deny = `[handoff-guard] Not run: the context is at ${pct(r.frac)}%, past ${pct(cfg.denyAt)}%. The handoff to .claude/brain/ is being written and this session will clear; the next session redoes this call. Make no more tool calls: end with one line saying where you stopped.`
        }
      }
    } catch {
      deny = null
    }
    if (deny) return { deny }
    const result = await next(e)
    try {
      const tool = typeof e.tool === 'string' ? e.tool : ''
      const ok = result && typeof result === 'object' && !('deny' in result && result.deny) && !(result as { isError?: boolean }).isError
      const path = (e as { file_path?: unknown; notebook_path?: unknown }).file_path ?? (e as { notebook_path?: unknown }).notebook_path
      if (ok && EDIT_TOOLS.has(tool) && typeof path === 'string') {
        await update($, editedSessionAtom, (xs: string[]) => [...xs.filter(x => x !== path), path].slice(-50))
        await update($, editedTurnAtom, (xs: string[]) => [...xs.filter(x => x !== path), path].slice(-50))
      }
      if (!e.agentId && result && typeof result === 'object') {
        const t = (result as { text?: unknown }).text ?? (result as { result?: unknown }).result
        if (typeof t === 'string') unmeasured += t.length / CHARS_PER_TOKEN
      }
    } catch {
      // Observing only.
    }
    return result
  })

  on('session.compact', async ($, e, next) => {
    if (e.agentId || e.trigger === 'precompute') return next(e)
    try {
      const cfg = await read($, configAtom)
      if (cfg.mode !== 'off' && !(await read($, sessionOffAtom)) && !(await read($, writtenAtom)) && !inFlight) {
        await doHandoff($, false)
      }
    } catch {
      // Never block compaction.
    }
    const result = await next(e)
    try {
      if (result && typeof result === 'object' && !('skip' in result)) {
        // Compaction is a fresh start for the context: the next one writes again.
        await update($, writtenAtom, () => false)
        await measure($, 'compact')
      }
    } catch {
      // Observing only.
    }
    return result
  })

  on('command.run', { command: 'handoff' }, async ($, e) => {
    try {
      return await runCommand($, typeof e.args === 'string' ? e.args : '')
    } catch (err) {
      return { text: 'handoff-guard: ' + errText(err) }
    }
  })

  // The band, one kit line: a bold label, the context chip in the level's tone (ok, accent, danger;
  // muted before the first reading), then what to do and the last handoff on the right side: quiet,
  // or in the default text color once the handoff is due (kit.line draws its right side quiet).
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const props = (e.props ?? {}) as { hasSurvey?: boolean }
    const cfg = await read($, configAtom)
    if (props.hasSurvey === true || !cfg.band) return next(e)
    const r = await read($, readingAtom)
    const last = await read($, lastBriefAtom)
    const parts = bandParts(r, cfg, {
      lastWhen: last ? last.when : undefined,
      busy: await read($, busyAtom),
      sessionOff: await read($, sessionOffAtom),
      resumed: (await read($, resumedAtom)) || undefined,
    })
    const ui = $.ui.resolve(e)
    const { Box } = ui
    const kit = makeKit(ui as unknown as Elements, e.surface)
    const chips = [{ text: parts.chip, tone: parts.tone }]
    const right = parts.right.join(' · ')
    const drawn = (
      parts.urgent && right
        ? Box({
            flexDirection: 'row',
            justifyContent: 'space-between',
            columnGap: 2,
            children: [kit.line('handoff', chips) as ReturnType<typeof Box>, kit.text(right, { wrap: 'truncate' }) as ReturnType<typeof Box>],
          })
        : kit.line('handoff', chips, parts.right)
    ) as ReturnType<typeof Box>
    const line = Box({ key: 'handoff-guard-band', flexDirection: 'column', children: [drawn] })
    const theirs = await next(e)
    if (!theirs) return line
    return Box({ flexDirection: 'column', children: [line, theirs] })
  })

  // The pane, drawn with the kit: a hero for the handoff state, tiles, the readings, the last brief, buttons.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const cfg = await read($, configAtom)
    const r = await read($, readingAtom)
    const history = await read($, historyAtom)
    const last = await read($, lastBriefAtom)
    const busy = await read($, busyAtom)
    const off = await read($, sessionOffAtom)
    const ui = $.ui.resolve(e)
    const kit = makeKit(ui as unknown as Elements, e.surface)
    const level = r ? levelOf(r.frac, cfg) : 'ok'
    const tone: Tone = r ? LEVEL_TONE[level] : 'muted'

    const hero = kit.hero({
      kicker: 'handoff guard',
      title: heroTitle(r, cfg, { busy, sessionOff: off }),
      sub: [
        r && r.tokens !== null && r.window !== null ? `${tokensShort(r.tokens)} of ${tokensShort(r.window)} tokens` : '',
        `mode ${cfg.mode}${off ? ' (off this session)' : ''}`,
        last ? `last handoff ${last.when}` : 'no handoff yet',
      ]
        .filter(Boolean)
        .join(' · '),
      tone: busy ? 'info' : tone,
    })

    const tiles = kit.tiles([
      { label: 'Context', value: r ? `${pct(r.frac)}%` : '--', tone },
      { label: 'Warn at', value: `${pct(cfg.warnAt)}%`, tone: LEVEL_TONE.warn },
      { label: 'Handoff at', value: `${pct(cfg.handoffAt)}%`, tone: 'danger' },
      { label: 'Mode', value: off ? `${cfg.mode} (off)` : cfg.mode, tone: cfg.mode === 'off' || off ? 'muted' : cfg.mode === 'auto' ? 'accent' : 'info' },
    ])

    const shown = history.slice(-10)
    const readings: unknown[] = shown.length
      ? shown.map((h, i) => {
          const lv = levelOf(h.frac, cfg)
          return kit.row({
            key: `reading-${i}`,
            left: [kit.pill(lv.padEnd(4), LEVEL_TONE[lv]), whenOf(h.at).slice(11), kit.text(h.where.padEnd(8), { color: QUIET })],
            right: [kit.bar(Math.min(1, h.frac), { width: 20, tone: LEVEL_TONE[lv] })],
          })
        })
      : [kit.text('none yet', { color: QUIET })]

    const brief: unknown[] = last
      ? [
          kit.row({
            left: [
              kit.pill(last.source, last.source === 'facts' ? 'accent' : 'ok'),
              kit.text(last.path, { color: QUIET, wrap: 'truncate-start' }),
            ],
          }),
          last.flagged.length ? kit.row({ left: [kit.pill('unverified', 'accent'), last.flagged.join(', ')] }) : null,
          ui.Markdown({ text: last.preview.split('\n').slice(0, 60).join('\n') }),
        ]
      : [kit.text('No handoff written for this project yet. /handoff writes one.', { color: QUIET })]

    return kit.page([
      hero,
      tiles,
      // A full-width Svg bar where the surface draws Svg, the 40-column text bar on the terminal.
      r ? kit.progress(Math.min(1, r.frac), kit.surface === 'terminal' ? { width: 40, tone } : { tone }) : null,
      kit.stack([kit.header(`Readings · ${history.length}`, history.length > shown.length ? `last ${shown.length}` : undefined), ...readings]),
      kit.stack([kit.header('Last handoff', last ? last.when : 'none yet'), ...brief]),
      kit.buttons([
        { key: 'write', label: 'Write handoff', hotkey: 'w', plain: true, onPress: () => doHandoff($, false) },
        { key: 'close', label: 'Close', hotkey: 'c', plain: true, onPress: () => $.ui.close({ id: PANE }) },
      ]),
    ]) as never
  })
}

files.hooks/logic.ts:
// handoff-guard: pure logic, no $ calls, so every rule here is unit tested on its own.
//
// Config merge and thresholds, the band, fact extraction from the transcript, the brief
// template and its validation, the unverified-figures pass, and the text transforms that
// write the handoff files (.claude/brain/{project,log,decisions,questions}.md) in the
// handoff folder format the README describes.

import type { Config, Mode, Reading } from '../types'

export const MODES: readonly Mode[] = ['ask', 'auto', 'off']

export const DEFAULTS: Config = {
  warnAt: 0.7,
  handoffAt: 0.85,
  reaskAt: 0.92,
  denyAt: 0.95,
  mode: 'ask',
  model: 'haiku',
  maxBriefTokens: 2000,
  band: true,
}

export const HELP = [
  '/handoff                 write the handoff into .claude/brain/ now (no clear)',
  '/handoff clear           write the handoff, then /clear and resume from it',
  '/handoff status          context fill, last handoff time and path',
  '/handoff show            pane: last brief and readings',
  '/handoff mode ask|auto|off',
  '/handoff at <0-1>        handoff level (default 0.85)',
  '/handoff warn <0-1>      warning level (default 0.70)',
  '/handoff band on|off',
].join('\n')

// ---------------------------------------------------------------- config

function frac(v: unknown): number | undefined {
  return typeof v === 'number' && Number.isFinite(v) && v > 0 && v <= 1 ? v : undefined
}

/** Keeps only the known, well-typed fields of one config layer. */
export function sanitize(raw: unknown): Partial<Config> {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {}
  const r = raw as Record<string, unknown>
  const out: Partial<Config> = {}
  for (const k of ['warnAt', 'handoffAt', 'reaskAt', 'denyAt'] as const) {
    const f = frac(r[k])
    if (f !== undefined) out[k] = f
  }
  if (typeof r.mode === 'string' && (MODES as readonly string[]).includes(r.mode)) out.mode = r.mode as Mode
  if (typeof r.model === 'string' && r.model.trim()) out.model = r.model.trim()
  if (typeof r.maxBriefTokens === 'number' && Number.isFinite(r.maxBriefTokens)) {
    out.maxBriefTokens = Math.min(8000, Math.max(300, Math.round(r.maxBriefTokens)))
  }
  if (typeof r.band === 'boolean') out.band = r.band
  return out
}

/** Defaults, then each layer in order (user file, project file, $.store), later wins. */
export function mergeConfig(...layers: unknown[]): Config {
  let cfg: Config = { ...DEFAULTS }
  for (const l of layers) cfg = { ...cfg, ...sanitize(l) }
  // Keep the levels in order: warn <= handoff <= reask <= deny.
  if (cfg.warnAt > cfg.handoffAt) cfg.warnAt = cfg.handoffAt
  if (cfg.reaskAt < cfg.handoffAt) cfg.reaskAt = Math.min(1, cfg.handoffAt + 0.05)
  if (cfg.denyAt < cfg.reaskAt) cfg.denyAt = Math.min(1, Math.max(cfg.reaskAt, cfg.handoffAt + 0.1))
  return cfg
}

/** "0.8", "80" or "80%" as 0.8; null when it is not in (0, 1]. */
export function parseFraction(arg: string): number | null {
  const s = arg.trim()
  if (!s) return null
  const pct = s.endsWith('%')
  const n = Number(pct ? s.slice(0, -1) : s)
  if (!Number.isFinite(n)) return null
  const f = pct || n > 1 ? n / 100 : n
  return f > 0 && f <= 1 ? Math.round(f * 1000) / 1000 : null
}

// ---------------------------------------------------------------- readings and levels

export type Level = 'ok' | 'warn' | 'due'

/** A usage() context block as a reading; null when it carries no usable figure. */
export function readingOf(context: unknown, at: number, where: string, extraTokens = 0): Reading | null {
  if (!context || typeof context !== 'object') return null
  const c = context as { tokens?: unknown; window?: unknown; percent?: unknown }
  const tokens = typeof c.tokens === 'number' && Number.isFinite(c.tokens) ? c.tokens : null
  const window = typeof c.window === 'number' && Number.isFinite(c.window) && c.window > 0 ? c.window : null
  let f: number | null = null
  if (tokens !== null && window !== null) f = (tokens + Math.max(0, extraTokens)) / window
  else if (typeof c.percent === 'number' && Number.isFinite(c.percent)) f = c.percent / 100
  if (f === null || !Number.isFinite(f) || f < 0) return null
  return { tokens: tokens === null ? null : tokens + Math.max(0, extraTokens), window, frac: Math.min(f, 1.5), at, where }
}

export function levelOf(f: number, cfg: Config): Level {
  if (f >= cfg.handoffAt) return 'due'
  if (f >= cfg.warnAt) return 'warn'
  return 'ok'
}

export const pct = (f: number) => Math.round(f * 100)

/** The kit tone of a level (the kit's Tone names): ok, accent (the Claude orange, not the warning
 *  key) at warnAt, danger at handoffAt. */
export const LEVEL_TONE: Record<Level, 'ok' | 'accent' | 'danger'> = { ok: 'ok', warn: 'accent', due: 'danger' }

/** The band's parts: the chip (`ctx 41%`), its kit tone (muted before the first reading), the right
 *  side (what to do, then the last or resumed handoff) and whether it is urgent: at or past
 *  handoffAt the right side is drawn in the default text color, else quiet. */
export type BandParts = { chip: string; tone: 'ok' | 'accent' | 'danger' | 'muted'; right: string[]; urgent: boolean }

/** The one-line band, drawn as kit.line('handoff', [chip], right): `handoff  ● ctx 41%   last 14:02`. */
export function bandParts(
  r: Reading | null,
  cfg: Config,
  o: { lastWhen?: string; busy?: boolean; sessionOff?: boolean; resumed?: string } = {},
): BandParts {
  if (!r) return { chip: 'ctx --', tone: 'muted', right: o.lastWhen ? [`last ${shortWhen(o.lastWhen)}`] : [], urgent: false }
  const level = levelOf(r.frac, cfg)
  const bits: string[] = []
  if (o.busy) bits.push('writing handoff…')
  else if (level === 'due') {
    if (cfg.mode === 'off' || o.sessionOff) bits.push('handoff due · guard off')
    else bits.push(cfg.mode === 'auto' ? 'auto handoff' : 'handoff due: /handoff clear')
  } else if (level === 'warn') bits.push('/handoff at a stopping point')
  if (o.resumed) bits.push(`resumed from handoff ${shortWhen(o.resumed)}`)
  else if (o.lastWhen) bits.push(`last ${shortWhen(o.lastWhen)}`)
  return { chip: `ctx ${pct(r.frac)}%`, tone: LEVEL_TONE[level], right: bits, urgent: level === 'due' }
}

/** "2026-10-09 14:02" as "14:02" when it is today's, else as written. */
export function shortWhen(when: string, today?: string): string {
  if (today && when.startsWith(today + ' ')) return when.slice(today.length + 1)
  return when
}

// ---------------------------------------------------------------- time

const two = (n: number) => String(n).padStart(2, '0')

export function dateOf(ms: number): string {
  const d = new Date(ms)
  return `${d.getFullYear()}-${two(d.getMonth() + 1)}-${two(d.getDate())}`
}

export function whenOf(ms: number): string {
  const d = new Date(ms)
  return `${dateOf(ms)} ${two(d.getHours())}:${two(d.getMinutes())}`
}

// ---------------------------------------------------------------- facts from the transcript

/** The slice of a $.session.messages() row this mod reads. */
export type Msg = {
  role: string
  text: string
  toolUses?: readonly { tool: string; input?: Record<string, unknown>; result?: unknown; text?: string; isError?: boolean }[]
}

// Harness signals that arrive as user messages but are never the user's words (from auto-handoff).
const META_PREFIXES = [
  'Stop hook feedback',
  '[handoff-guard]',
  'Resume from the handoff in .claude/brain/',
  '[Image',
  '<system-reminder>',
  '<command-name>',
  '<local-command',
  '<task-notification>',
  '[Request interrupted',
]

export const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

export function isMeta(text: string): boolean {
  const t = text.trim()
  return META_PREFIXES.some(p => t.startsWith(p))
}

export type Transcript = {
  lastPrompt: string
  lastAnswer: string
  openQuestions: string[]
  edited: string[]
}

/** The last real prompt, the last answer, unanswered AskUserQuestion calls and edited files. */
export function extractFromMessages(messages: readonly Msg[]): Transcript {
  let lastPrompt = ''
  let lastAnswer = ''
  const open: string[] = []
  const answered = new Set<string>()
  const edited = new Set<string>()
  for (const m of Array.isArray(messages) ? messages : []) {
    if (!m || typeof m !== 'object') continue
    const text = typeof m.text === 'string' ? m.text.trim() : ''
    if (m.role === 'user' && text && !isMeta(text)) lastPrompt = text
    if (m.role === 'assistant' && text) lastAnswer = text
    for (const t of Array.isArray(m.toolUses) ? m.toolUses : []) {
      if (!t || typeof t.tool !== 'string') continue
      const input = t.input && typeof t.input === 'object' ? t.input : {}
      const path = input.file_path ?? input.notebook_path
      if (EDIT_TOOLS.has(t.tool) && typeof path === 'string' && !t.isError) edited.add(path)
      if (t.tool === 'AskUserQuestion') {
        const qs = Array.isArray(input.questions) ? input.questions : []
        const unanswered = t.isError === true || (t.result === undefined && t.text === undefined)
        for (const q of qs) {
          const s = q && typeof q === 'object' && typeof (q as { question?: unknown }).question === 'string' ? (q as { question: string }).question.trim() : ''
          if (!s) continue
          if (unanswered) open.push(s)
          else answered.add(s)
        }
      }
    }
  }
  const openQuestions = [...new Set(open.filter(q => !answered.has(q)))].slice(-5)
  return { lastPrompt, lastAnswer, openQuestions, edited: [...edited] }
}

export type Facts = {
  cwd: string
  when: string
  branch: string
  commits: string[]
  editedTurn: string[]
  editedSession: string[]
  lastPrompt: string
  lastAnswer: string
  openQuestions: string[]
  stage: string
  ctxPercent: number | null
  ctxTokens: number | null
  ctxWindow: number | null
}

export function clip(text: string, max: number): string {
  const t = text.replace(/\s+/g, ' ').trim()
  return t.length > max ? t.slice(0, max - 1).trimEnd() + '…' : t
}

/** Strips credential-shaped strings before anything is written or sent. */
export function redact(text: string): string {
  return text
    .replace(/\b([A-Z][A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD|PASSWD)[A-Z0-9_]*)\s*[=:]\s*\S+/g, '$1=[redacted]')
    .replace(/\b(?:sk-[A-Za-z0-9_-]{16,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|xox[abprs]-[A-Za-z0-9-]{10,}|AKIA[0-9A-Z]{16}|AIza[0-9A-Za-z_-]{30,})/g, '[redacted]')
    .replace(/\b[A-Za-z0-9_-]{40,}\b/g, m => (/^[0-9a-f]{40}$/.test(m) ? m : '[redacted]'))
}

function rel(path: string, cwd: string): string {
  const base = cwd.replace(/\/+$/, '') + '/'
  return cwd && path.startsWith(base) ? path.slice(base.length) : path
}

/** The facts block: everything here came from code, not from a model. */
export function factsBlock(f: Facts): string {
  const list = (xs: string[], empty = 'None.') => (xs.length ? xs.map(x => `- ${x}`).join('\n') : empty)
  const ctx =
    f.ctxPercent === null
      ? 'unknown'
      : `${f.ctxPercent}%` + (f.ctxTokens !== null && f.ctxWindow !== null ? ` (${f.ctxTokens} of ${f.ctxWindow} tokens)` : '')
  const lines = [
    '## Facts (from code)',
    `- Written: ${f.when}`,
    `- Working directory: ${f.cwd || 'unknown'}`,
    `- Git branch: ${f.branch || 'not a git repository'}`,
    `- Context at handoff: ${ctx}`,
  ]
  if (f.stage) lines.push(`- Pipeline stage: ${f.stage}`)
  lines.push('', '### Last commits', list(f.commits))
  lines.push('', '### Files edited this turn', list(f.editedTurn.map(p => rel(p, f.cwd))))
  const earlier = f.editedSession.filter(p => !f.editedTurn.includes(p))
  lines.push('', '### Files edited earlier this session', list(earlier.slice(-20).map(p => rel(p, f.cwd))))
  lines.push('', '### Unanswered questions to the user', list(f.openQuestions))
  lines.push('', '### Last user request', f.lastPrompt ? clip(redact(f.lastPrompt), 600) : 'None found.')
  lines.push('', '### Last answer (excerpt)', f.lastAnswer ? clip(redact(f.lastAnswer), 600) : 'None found.')
  return lines.join('\n')
}

// ---------------------------------------------------------------- the brief

export const HEADINGS = ['Status', 'Next steps', 'Dead ends', 'Open questions', 'Decisions', 'Log'] as const
export type Heading = (typeof HEADINGS)[number]

export function briefTemplate(maxWords: number): string {
  return `Write the judgment sections of a session handoff for the next session in this project. Use exactly these six headings, in this order, and nothing before the first:

## Status
Two to four sentences: where the work stands, what works, what is broken.

## Next steps
- One to three concrete next steps, most important first.

## Dead ends
- Approaches tried and dropped this session, with the reason. Write "None." if there were none.

## Open questions
- Questions only the human can answer. Write "None." if there are none.

## Decisions
- One line per decision someone outside this repo should know, as a pointer (a file, an ADR or a commit), not the reasoning. Write "None." if there are none.

## Log
One line, past tense, under 250 characters: what changed. Next: the next step. Blocked: only when something is.

Rules: use only what the conversation and the Facts block support. Copy any number exactly from the Facts block and write no other figures. No secrets, tokens, credentials, phone numbers or personal names. Plain sentences, no em dashes. Under ${maxWords} words in total.`
}

export function wordsFor(maxBriefTokens: number): number {
  return Math.max(120, Math.min(600, Math.round(maxBriefTokens * 0.3)))
}

/** The fork's one user message: it already sees the conversation, so only facts and the template. */
export function forkPrompt(facts: string, maxWords: number): string {
  return `[handoff-guard] A side request from a mod, not from the user, and not part of the task: the context window is nearly full, so the session is writing its handoff before it clears. Do not call tools and do not continue the task. Reply with the handoff only.

${facts}

---

${briefTemplate(maxWords)}`
}

/** A compact transcript for the $.model.complete fallback, which has no conversation of its own. */
export function renderTranscript(messages: readonly Msg[], maxChars = 60_000): string {
  const rows = (Array.isArray(messages) ? messages : []).slice(-80).map(m => {
    const role = m.role === 'user' && isMeta(String(m.text ?? '')) ? 'system signal (not the user)' : m.role
    const text = clip(redact(String(m.text ?? '')), 1500)
    const tools = (Array.isArray(m.toolUses) ? m.toolUses : []).map(
      t => `  [tool ${t.tool}${t.isError ? ' ERROR' : ''}] ${clip(redact(JSON.stringify(t.input ?? {})), 200)}`,
    )
    return [`### ${role}`, text, ...tools].filter(Boolean).join('\n')
  })
  const joined = rows.join('\n\n')
  return joined.length > maxChars ? joined.slice(-maxChars) : joined
}

export function completePrompt(facts: string, transcript: string, maxWords: number): string {
  // Data first, instructions last (as auto-handoff does).
  return `${facts}\n\n## Conversation (most recent part)\n${transcript || '(empty)'}\n\n---\n\n${briefTemplate(maxWords)}`
}

export type Parsed = Record<Heading, string>

/** The reply's six sections, or null when any heading is missing (then the facts stand alone). */
export function parseBrief(text: unknown): Parsed | null {
  if (typeof text !== 'string' || !text.trim()) return null
  const t = text.replace(/^```[a-z]*\n?/i, '').replace(/\n?```\s*$/, '')
  const re = /^#{1,4}\s*\**\s*(Status|Next steps|Dead ends|Open questions|Decisions|Log)\s*\**\s*:?\s*$/gim
  const marks: { h: Heading; start: number; end: number }[] = []
  let m: RegExpExecArray | null
  while ((m = re.exec(t)) !== null) {
    const h = HEADINGS.find(x => x.toLowerCase() === m![1].toLowerCase())
    if (h) marks.push({ h, start: m.index, end: m.index + m[0].length })
  }
  const out: Partial<Parsed> = {}
  marks.forEach((mk, i) => {
    if (out[mk.h] !== undefined) return
    out[mk.h] = t.slice(mk.end, i + 1 < marks.length ? marks[i + 1].start : t.length).trim()
  })
  return HEADINGS.every(h => out[h] !== undefined) ? (out as Parsed) : null
}

const NONE = /^(none|n\/a|nothing|no\b.*(?:dead ends?|questions?|decisions?))\.?$/i

/** Bullet lines of a section ("None." gives []); prose without bullets is one item. */
export function itemsOf(section: string): string[] {
  const lines = section.split('\n').map(l => l.trim()).filter(Boolean)
  const bullets = lines.filter(l => /^([-*•]|\d+[.)])\s+/.test(l)).map(l => l.replace(/^([-*•]|\d+[.)])\s+/, '').trim())
  const items = bullets.length ? bullets : lines.length ? [lines.join(' ')] : []
  return items.map(i => i.replace(/\s+/g, ' ').trim()).filter(i => i && !NONE.test(i))
}

// ---------------------------------------------------------------- unverified figures

// A figure: 93, 93.5, 1,200, 72%, 93k, 3x. Not part of a word, path, version-free id or date.
const FIGURE = /(?<![\w.\/#:@-])(\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)(%|k\b|K\b|x\b)?(?![\w\/]|\.\d|-\d)/g

function valueOf(num: string, suffix: string | undefined): number {
  const n = Number(num.replace(/,/g, ''))
  return suffix === 'k' || suffix === 'K' ? n * 1000 : n
}

/** Masks spans whose numbers are not claims: inline code, ISO dates, times, versions. */
function maskSpans(text: string): string {
  return text
    .replace(/`[^`\n]*`/g, s => ' '.repeat(s.length))
    .replace(/\b\d{4}-\d{2}-\d{2}\b/g, s => ' '.repeat(s.length))
    .replace(/\b\d{1,2}:\d{2}\b/g, s => ' '.repeat(s.length))
    .replace(/\bv?\d+\.\d+\.\d+\b/g, s => ' '.repeat(s.length))
}

/**
 * Marks every figure in the model's text that the facts do not hold, by appending
 * " (unverified)". Single-digit counts (step 1, 3 files) are left alone. Borrowed from
 * auto-handoff's markUnverifiedFigures, widened from token figures to any number.
 */
export function markUnverifiedFigures(text: string, facts: string): { text: string; flagged: string[] } {
  const allowed: number[] = []
  for (const m of maskSpans(facts).matchAll(FIGURE)) allowed.push(valueOf(m[1], m[2]))
  for (const m of facts.matchAll(/\d+(?:\.\d+)?/g)) allowed.push(Number(m[0]))
  const masked = maskSpans(text)
  const flagged: string[] = []
  const cuts: { at: number; fig: string }[] = []
  for (const m of masked.matchAll(FIGURE)) {
    const v = valueOf(m[1], m[2])
    if (!m[2] && Number.isInteger(v) && v < 10) continue
    const k = m[2] === 'k' || m[2] === 'K'
    if (allowed.some(a => (k ? Math.abs(a - v) < 1000 : a === v))) continue
    flagged.push(m[0])
    cuts.push({ at: (m.index ?? 0) + m[0].length, fig: m[0] })
  }
  let out = text
  for (const c of cuts.reverse()) out = out.slice(0, c.at) + ' (unverified)' + out.slice(c.at)
  return { text: out, flagged }
}

// ---------------------------------------------------------------- sections for the brain files

export type Sections = {
  /** Body of `## Status today`. */
  status: string
  /** Body of `## Next` (bullets). */
  next: string
  /** Body of `## Dead ends`, or null to leave the section as it is. */
  deadEnds: string | null
  /** One log line, without the date prefix. */
  log: string
  decisions: string[]
  questions: string[]
}

const bullets = (xs: string[]) => xs.map(x => `- ${x}`).join('\n')

function ctxPhrase(f: Facts): string {
  return f.ctxPercent === null ? '' : `, context ${f.ctxPercent}%`
}

function atCtx(f: Facts): string {
  return f.ctxPercent === null ? '' : ` at ${f.ctxPercent}% context`
}

/** What goes into the files: the model's sections when they parsed, else facts only. */
export function buildSections(parsed: Parsed | null, f: Facts): Sections {
  const stamp = `(Written by handoff-guard ${f.when}${ctxPhrase(f)}${f.branch ? `, branch ${f.branch}` : ''}${parsed ? '' : ', facts only'}.)`
  const qs = [...f.openQuestions]
  if (parsed) {
    for (const q of itemsOf(parsed['Open questions'])) if (!qs.includes(q)) qs.push(q)
    const next = itemsOf(parsed['Next steps']).slice(0, 5)
    const dead = itemsOf(parsed['Dead ends'])
    const log = itemsOf(parsed.Log)[0] ?? ''
    return {
      status: clip(parsed.Status.replace(/^[-*]\s+/gm, ''), 1200) + '\n\n' + stamp,
      next: next.length ? bullets(next) : '- Re-read the last request in the log and continue.',
      deadEnds: dead.length ? bullets(dead.slice(0, 6)) : null,
      log: oneLine(log || `Handed off by handoff-guard${atCtx(f)}.`),
      decisions: itemsOf(parsed.Decisions).slice(0, 5).map(x => oneLine(x)),
      questions: qs.slice(0, 5).map(x => oneLine(x)),
    }
  }
  const parts: string[] = []
  if (f.commits.length) parts.push(`Last commits: ${f.commits.slice(0, 3).join('; ')}.`)
  const edited = (f.editedTurn.length ? f.editedTurn : f.editedSession).slice(-6).map(p => rel(p, f.cwd))
  if (edited.length) parts.push(`Edited: ${edited.join(', ')}.`)
  if (f.stage) parts.push(`Pipeline stage: ${f.stage}.`)
  if (f.lastPrompt) parts.push(`Last request: "${clip(redact(f.lastPrompt), 300)}"`)
  const next = ['Re-read the last request below and check git status before continuing.']
  if (f.lastPrompt) next.push(`Continue: ${clip(redact(f.lastPrompt), 160)}`)
  return {
    status: (parts.join(' ') || 'No facts could be collected.') + '\n\n' + stamp,
    next: bullets(next),
    deadEnds: null,
    log: oneLine(
      `(handoff-guard, facts only) Handed off${atCtx(f)}${edited.length ? ` after editing ${edited.slice(0, 3).join(', ')}` : ''}. Next: re-read the last request.`,
    ),
    decisions: [],
    questions: qs.slice(0, 5).map(x => oneLine(x)),
  }
}

/** The whole brief as shown in the pane: sections, then the facts. */
export function briefMarkdown(s: Sections, facts: string): string {
  return [
    '## Status today',
    s.status,
    '',
    '## Next',
    s.next,
    ...(s.deadEnds ? ['', '## Dead ends', s.deadEnds] : []),
    '',
    `Log: ${s.log}`,
    ...(s.decisions.length ? ['', 'Decisions:', bullets(s.decisions)] : []),
    ...(s.questions.length ? ['', 'Open questions:', bullets(s.questions)] : []),
    '',
    facts,
  ].join('\n')
}

// ---------------------------------------------------------------- handoff folder file shapes

/** One data line's text: no newlines, no leading bullet, under 300 characters (the handoff folder's line rule). */
export function oneLine(text: string, max = 290): string {
  return clip(redact(text.replace(/^\s*[-*]\s+/, '')), max)
}

export function datedLine(date: string, text: string): string {
  return `- ${date} — ${oneLine(text)}`
}

export function slugOf(cwd: string): string {
  const name = cwd.replace(/\/+$/, '').split('/').pop() ?? ''
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'project'
}

/** The handoff folder's project.md template, filled in, for a project that has no .claude/brain/ yet. */
export function projectTemplate(slug: string, date: string): string {
  return `---
type: project
name: "${slug}"
group: ""
status: active
role: ""
public: false
live_url:
summary: "${slug}: handoff written by handoff-guard; replace this line with what the project is."
tags: [project, active]
created: ${date}
updated: ${date}
---

## What it is

Not filled in yet: handoff-guard created this file. Describe the project here.

## Why

Not filled in yet.

## Status today

## Next

## Dead ends
`
}

export const FILE_HEADERS: Record<'log.md' | 'decisions.md' | 'questions.md', string> = {
  'log.md': '# Log\n\nOne line per session, newest last: `- YYYY-MM-DD — what changed, what is next, what is blocked`.\n',
  'decisions.md':
    '# Decisions\n\nOne line per decision worth knowing outside this repo: `- YYYY-MM-DD — decision and why`. Append only; to reverse one, add a new dated line.\n',
  'questions.md':
    '# Questions\n\nOne line per question only the human can answer: `- YYYY-MM-DD — question`. Remove a line once it is answered and record the answer as a decision.\n',
}

/**
 * Rewrites the body of `## <heading>` (up to the next `## ` or the end), keeping every
 * other section and the frontmatter. A missing section is added at the end.
 */
export function replaceSection(doc: string, heading: string, body: string): string {
  const lines = doc.replace(/\r\n/g, '\n').split('\n')
  const head = `## ${heading}`
  const start = lines.findIndex(l => l.trim() === head)
  const block = [head, '', ...body.trim().split('\n'), '']
  if (start === -1) {
    const trimmed = lines.join('\n').replace(/\s+$/, '')
    return trimmed + '\n\n' + block.join('\n')
  }
  let end = lines.length
  for (let i = start + 1; i < lines.length; i++) {
    if (/^## /.test(lines[i])) {
      end = i
      break
    }
  }
  const out = [...lines.slice(0, start), ...block, ...lines.slice(end)]
  return out.join('\n').replace(/\n{3,}/g, '\n\n').replace(/\s*$/, '\n')
}

/** Sets `key: value` in the frontmatter block, when there is one. */
export function setFrontmatter(doc: string, key: string, value: string): string {
  const m = /^---\n([\s\S]*?)\n---\n/.exec(doc)
  if (!m) return doc
  const re = new RegExp(`^${key}:.*$`, 'm')
  const front = re.test(m[1]) ? m[1].replace(re, `${key}: ${value}`) : `${m[1]}\n${key}: ${value}`
  return `---\n${front}\n---\n` + doc.slice(m[0].length)
}

/** Appends a dated line unless the identical line is there (the handoff folder's append rule). */
export function appendLine(doc: string, line: string): { doc: string; added: boolean } {
  const body = doc.replace(/\s+$/, '')
  if (body.split('\n').includes(line)) return { doc: body + '\n', added: false }
  return { doc: body + '\n' + line + '\n', added: true }
}

/**
 * The session's log line: replaces the line this session wrote before when it is still
 * the last one (a second handoff in one session refines it), else appends.
 */
export function upsertLogLine(doc: string, line: string, previous: string | undefined): string {
  const lines = doc.replace(/\s+$/, '').split('\n')
  if (previous && lines.length && lines[lines.length - 1] === previous) {
    lines[lines.length - 1] = line
    return lines.join('\n') + '\n'
  }
  return appendLine(doc, line).doc
}

